+    Assert.equal((await secondSave).status, "success");
+    if (newestSave) {
+      Assert.equal((await newestSave).status, "success");
+    }
+    transaction = realTransaction;
+  }
+  Assert.equal(
+    (await otherCalendar.getItem(original.id)).title,
+    "Newest window",
+    "Separate stores share the transaction order"
+  );
+  Assert.ok(!second.open);
+  Assert.equal(second.draft, null);
+  Assert.ok(!dialog.open);
+  Assert.equal(dialog.draft, null);
+  Assert.equal(await calendar.getItem(original.id), null);
+});
