+  const sourceAgain = await queueCalendarEventEdit(
+    source,
+    async identity => identity
+  );
+  Assert.deepEqual(
+    sourceAgain,
+    source,
+    "Idle queues remove the old calendar alias"
+  );
+  const destinationAgain = await queueCalendarEventEdit(
+    moved,
+    async identity => identity
+  );
+  Assert.deepEqual(
+    destinationAgain,
+    moved,
+    "Idle queues remove the destination alias"
+  );
+});
