+add_task(
+  async function test_transactionsKeepNotificationDataAndResultsSerializable() {
+    const original = await createEvent();
+    await startEdit(original);
+    changeTitle("Notify");
+    const notifications = [];
+    const checkAndSend = cal.itip.checkAndSend;
+    cal.itip.checkAndSend = (...args) => notifications.push(args);
+    registerCleanupFunction(() => {
+      cal.itip.checkAndSend = checkAndSend;
+    });
+    const actions = [];
+    const result = await save({
+      store: {
+        getState: () => store.getState(),
+        dispatch: action => {
+          actions.push(action);
+          store.dispatch(action);
+        },
+      },
+      transact: (event, oldEvent) =>
+        manager.commit(
+          new CalModifyTransaction(event, calendar, oldEvent, {
+            responseMode: Ci.calIItipItem.AUTO,
+          })
+        ),
+    });
+    cal.itip.checkAndSend = checkAndSend;
+    Assert.equal(result.status, "success");
+    Assert.equal(notifications.length, 1);
+    Assert.equal(notifications[0][0], Ci.calIOperationListener.MODIFY);
+    Assert.equal(notifications[0][1].title, "Notify");
+    Assert.equal(notifications[0][2].title, "Original");
+    Assert.equal(notifications[0][3].responseMode, Ci.calIItipItem.AUTO);
+    Assert.deepEqual(JSON.parse(JSON.stringify(result)), result);
+    for (const action of actions) {
+      Assert.deepEqual(
+        JSON.parse(JSON.stringify(action)),
+        action,
+        "Save actions contain data only"
+      );
+    }
+  }
+);
